 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not markers:
        return out
    rr = next((r for r in range(h) if all(v == 2 for v in grid[r])), None)
    if rr is not None:
        mr = min(r for r, c in markers)
        mxr = max(r for r, c in markers)
        if mr < rr:
            row = rr - (4 if rr - mr > 3 else 1)
        else:
            row = mr - 1
        if 0 <= row < h:
            out[row] = [8 if v == bg else v for v in out[row]]
    else:
        rc = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
        if rc is not None:
            mc = min(c for r, c in markers)
            col = mc + 1 if mc < rc else mc - 1
            if 0 <= col < w:
                for r in range(h):
                    if out[r][col] == bg:
                        out[r][col] = 8
    return out

if __name__ == '__main__':
    a=[[4]*7 for _ in range(12)]; a[1]=[2]*7; a[3][3:5]=[7,7]
    ao=[[4]*7 for _ in range(12)]; ao[1]=[2]*7; ao[2]=[8]*7; ao[3][3:5]=[7,7]
    b=[[4]*15 for _ in range(15)]; b[12]=[2]*15; b[9][7]=9; b[10][8]=9; b[11][8]=9
    bo=[[4]*15 for _ in range(15)]; bo[12]=[2]*15; bo[8]=[8]*15; bo[9][7]=9; bo[10][8]=9; bo[11][8]=9
    assert transform(a)==ao
    assert transform(b)==bo
    t=[[4]*17 for _ in range(14)]; t[3]=[2]*17; t[12][11:15]=[3]*4
    result=transform(t)
    print(result)
",
 "cross_profile": false
}

